        private static readonly Regex ModelPath = new Regex(@"^natives/stm/product/model/esf/(esf\d{3})/(\d{3})/([^/]+\.user\.2)$", RegexOptions.IgnoreCase);
        private static readonly Regex PartsPath = new Regex(@"^natives/stm/product/charparam/esf/(esf\d{3})/battle_ud/(esf\d{3})v\d+_model_parts\.user\.2$", RegexOptions.IgnoreCase);
        private static readonly Regex ResourcePrefix = new Regex(@"^Product/Model/esf/(esf\d{3})/(\d{3})/", RegexOptions.IgnoreCase);

        private static uint U32(byte[] b, int at) { return BitConverter.ToUInt32(b, at); }
        private static ulong U64(byte[] b, int at) { return BitConverter.ToUInt64(b, at); }
        private static bool Magic(byte[] b, int at, string value) { return b != null && at >= 0 && at <= b.Length - 4 && b[at] == value[0] && b[at + 1] == value[1] && b[at + 2] == value[2] && b[at + 3] == 0; }
        private static FixResult Warning(string text) { return new FixResult { Kind = "swap-stale", Warning = true, Message = text }; }

        // The root RSZ instance table only; never search the payload for a four-byte pattern.
        private static bool Table(byte[] b, bool scene, out int table, out uint count)
        {
            table = 0; count = 0;
            int header = scene ? 64 : 48;
            if (b == null || b.Length < header || !Magic(b, 0, scene ? "SCN" : "USR")) return false;
            ulong r = U64(b, scene ? 56 : 32);
            if (r < (ulong)header || (r & 1) != 0 || r > (ulong)b.Length || (ulong)b.Length - r < 48) return false;
            if (scene)
            {
                var spans = new List<KeyValuePair<ulong, ulong>>();
                Func<ulong, uint, uint, bool> span = delegate(ulong offset, uint n, uint width)
                {
                    if (n == 0) return true;
                    if (offset < 64 || (offset & 3) != 0 || offset > r || (ulong)n * width > r - offset) return false;
                    spans.Add(new KeyValuePair<ulong, ulong>(offset, offset + (ulong)n * width)); return true;
                };
                if (!span(64, U32(b, 4), 32) || !span(U64(b, 24), U32(b, 12), 8) || !span(U64(b, 32), U32(b, 8), 8)
                    || !span(U64(b, 40), U32(b, 16), 8) || !span(U64(b, 48), U32(b, 20), 16)) return false;
                spans = spans.OrderBy(s => s.Key).ToList();
                for (int i = 1; i < spans.Count; i++) if (spans[i].Key < spans[i - 1].Value) return false;
            }
            int at = (int)r;
            if (!Magic(b, at, "RSZ") || U32(b, at + 4) != 16) return false;
            uint objects = U32(b, at + 8), instances = U32(b, at + 12), users = U32(b, at + 16);
            ulong inst = U64(b, at + 24), data = U64(b, at + 32), user = U64(b, at + 40), remaining = (ulong)b.Length - r;
            if (instances == 0 || inst < 48UL + 4UL * objects || (inst & 3) != 0 || inst > remaining || 8UL * instances > remaining - inst) return false;
            ulong end = inst + 8UL * instances;
            if (data < end || data > remaining || ((r + data) & 15) != 0) return false;
            if (users > 0 && (user < end || user > data || 16UL * users > data - user)) return false;
            if (users == 0 && user != 0 && (user < end || user > remaining)) return false;
            for (uint i = 0; i < objects; i++) if (U32(b, at + 48 + checked((int)(4L * i))) >= instances) return false;
            table = at + (int)inst; count = instances;
            return U32(b, table) == 0 && U32(b, table + 4) == 0;
        }

        internal static FixResult RepairScene(ref byte[] data, GameReference reference, string path)
        {
            if (String.IsNullOrEmpty(path) || !path.StartsWith("natives/", StringComparison.OrdinalIgnoreCase) || !path.EndsWith(".scn.20", StringComparison.OrdinalIgnoreCase)) return null;
            int table; uint count;
            if (!Table(data, true, out table, out count)) return Warning("Scene was left unchanged: its structure could not be verified for the Alex update repair.");
            var offsets = new List<int>();
            for (uint i = 1; i < count; i++)
            {
                int at = table + (int)(8 * i);
                if (U32(data, at) != TimelineType) continue;
                uint crc = U32(data, at + 4);
                if (crc != TimelineOld && crc != TimelineCurrent) return Warning("Scene was left unchanged: its timeline signature is not a supported Alex update version.");
                if (crc == TimelineOld) offsets.Add(at + 4);
            }
            if (offsets.Count == 0) return null;
            byte[] current = reference == null ? null : reference.ReadGameFile(ModFixes.NormalizeNativePath(path));
            if (current == null && reference != null)
                foreach (string fallback in ReferenceScenes) { current = reference.ReadGameFile(fallback); if (current != null) break; }
            if (!Table(current, true, out table, out count)) return Warning("Scene was left unchanged: the current game's scene signature could not be verified.");
            bool found = false;
            for (uint i = 1; i < count; i++)
            {
                int at = table + (int)(8 * i);
                if (U32(current, at) != TimelineType) continue;
                if (U32(current, at + 4) != TimelineCurrent) return Warning("Scene was left unchanged: the game uses an unrecognized timeline version.");
                found = true;
            }
            if (!found) return Warning("Scene was left unchanged: the current game's timeline signature was not found.");
            byte[] repaired = (byte[])data.Clone();
            foreach (int at in offsets) Buffer.BlockCopy(BitConverter.GetBytes(TimelineCurrent), 0, repaired, at, 4);
            data = repaired;
            return new FixResult { Kind = "swap-scene", Count = offsets.Count, Changed = true, Message = "Character-swap scene updated for the Alex patch (the mod's scene and body references kept)." };
        }

        // Only complete, terminated UTF-16 resource strings, not arbitrary matching byte fragments.
        private static IEnumerable<KeyValuePair<int, string>> Resources(byte[] bytes)
        {
            if (bytes == null) yield break;
            for (int at = 0; at + 1 < bytes.Length; at += 2)
            {
                if (bytes[at + 1] != 0 || bytes[at] < 32 || bytes[at] > 126) continue;
                int end = at;
                while (end + 1 < bytes.Length && bytes[end + 1] == 0 && bytes[end] >= 32 && bytes[end] <= 126) end += 2;
                if (end + 1 < bytes.Length && bytes[end] == 0 && bytes[end + 1] == 0)
                {
                    string text = Encoding.Unicode.GetString(bytes, at, end - at);
                    int lead = 0; while (lead < text.Length && (text[lead] == '@' || text[lead] == ' ')) lead++;
                    if (lead < text.Length) yield return new KeyValuePair<int, string>(at + lead * 2, text.Substring(lead));
                }
                at = end;
            }
        }

        internal static byte[] RemapPrefix(byte[] data, string from, string to, out int changed)
        {
            changed = 0;
            if (data == null || from == null || to == null || from.Length != to.Length) return null;
            byte[] output = (byte[])data.Clone(), replacement = Encoding.Unicode.GetBytes(to);
            foreach (var resource in Resources(data))
            {
                if (!resource.Value.StartsWith(from + "/", StringComparison.OrdinalIgnoreCase)) continue;
                Buffer.BlockCopy(replacement, 0, output, resource.Key, replacement.Length); changed++;
            }
            return output;
        }

        internal static string NormalizedSha(byte[] data, string targetPrefix)
        {
            int count; byte[] normalized = RemapPrefix(data, targetPrefix, CanonicalPrefix, out count);
            return normalized == null || count == 0 ? null : ReplaceEngine.Sha(normalized);
        }

        internal static FixResult RepairUser(ref byte[] data, GameReference reference, string path) { return RepairUser(ref data, reference, path, Recipes); }
        internal static FixResult RepairUser(ref byte[] data, GameReference reference, string path, IEnumerable<UserRecipe> recipes)
        {
            path = ModFixes.NormalizeNativePath(path ?? "");
            Match model = ModelPath.Match(path), parts = PartsPath.Match(path);
            if (!model.Success && !parts.Success) return null;
            string basename = path.Substring(path.LastIndexOf('/') + 1);
            var candidates = recipes.Where(r => r.ModelParts == parts.Success && (r.ModelParts || String.Equals(r.Basename, basename, StringComparison.OrdinalIgnoreCase))
                && (!r.OwnSlotOnly || (model.Success && model.Groups[1].Value == "esf028" && ModelPath.IsMatch(r.CurrentPath ?? "") && model.Groups[2].Value != ModelPath.Match(r.CurrentPath).Groups[2].Value))).ToList();
            if (candidates.Count == 0)
                return path == "natives/stm/product/charparam/esf/esf030/battle_ud/esf030v01_model_parts.user.2"
                    ? Warning("This model-parts swap needs manual review; no verified repair is available for this file.") : null;
            int table; uint instances;
            if (!Table(data, false, out table, out instances)) return Warning("Swap physics file was left unchanged: its structure could not be verified.");
            string target;
            if (model.Success) target = "Product/Model/esf/" + model.Groups[1].Value + "/" + model.Groups[2].Value;
            else
            {
                if (!String.Equals(parts.Groups[1].Value, parts.Groups[2].Value, StringComparison.OrdinalIgnoreCase)) return Warning("Swap model-parts file was left unchanged: its fighter references disagree.");
                var all = Resources(data).Select(r => ResourcePrefix.Match(r.Value)).Where(m => m.Success && m.Groups[2].Value != "000").ToList();
                var prefixes = all.Where(m => m.Groups[2].Value != "000").Select(m => "Product/Model/esf/" + m.Groups[1].Value.ToLowerInvariant() + "/" + m.Groups[2].Value).Distinct(StringComparer.OrdinalIgnoreCase).ToList();
                if (prefixes.Count != 1 || all.Any(m => !String.Equals(m.Groups[1].Value, parts.Groups[1].Value, StringComparison.OrdinalIgnoreCase))) return Warning("Swap model-parts file was left unchanged: its target costume is ambiguous.");
                target = prefixes[0];
            }
            string oldSha = NormalizedSha(data, target);
            if (oldSha == null) return Warning("Swap physics file was left unchanged: its target resource references could not be verified.");
            bool knownOld = false;
            foreach (UserRecipe recipe in candidates)
            {
                bool oldMatches = String.Equals(recipe.OldNormalizedSha256, oldSha, StringComparison.OrdinalIgnoreCase);
                knownOld |= oldMatches;
                Match donor = ModelPath.Match(recipe.CurrentPath ?? "");
                string donorPrefix;
                if (donor.Success) donorPrefix = "Product/Model/esf/" + donor.Groups[1].Value + "/" + donor.Groups[2].Value;
                else donorPrefix = recipe.ModelParts ? DonorModelPrefix(recipe, reference) : null;
                if (donorPrefix == null) continue;
                byte[] current = reference == null ? null : reference.ReadGameFile(recipe.CurrentPath);
                if (current == null || !String.Equals(ReplaceEngine.Sha(current), recipe.CurrentSha256, StringComparison.OrdinalIgnoreCase) || !Table(current, false, out table, out instances)) continue;
                int changed; byte[] repaired = RemapPrefix(current, donorPrefix, target, out changed);
                if (changed == 0) continue;
                if (data.SequenceEqual(repaired)) return null;
                if (!oldMatches) continue;
                data = repaired;
                return new FixResult { Kind = "swap-user", Count = 1, Changed = true, Message = recipe.Name + " refreshed from the verified current game file, keeping the swap's target costume." };
            }
            return Warning(knownOld ? "Swap physics file was left unchanged: its approved current game file is unavailable or has changed." : "Swap physics file was left unchanged: it is customized or is not a recognized older version.");
        }

        private static string DonorModelPrefix(UserRecipe recipe, GameReference reference)
        {
            byte[] current = reference == null ? null : reference.ReadGameFile(recipe.CurrentPath);
            if (current == null || !String.Equals(ReplaceEngine.Sha(current), recipe.CurrentSha256, StringComparison.OrdinalIgnoreCase)) return null;
            var prefixes = Resources(current).Select(r => ResourcePrefix.Match(r.Value)).Where(m => m.Success && m.Groups[2].Value != "000").Select(m => "Product/Model/esf/" + m.Groups[1].Value.ToLowerInvariant() + "/" + m.Groups[2].Value).Distinct(StringComparer.OrdinalIgnoreCase).ToList();
            return prefixes.Count == 1 ? prefixes[0] : null;
        }
    }

    // 1.0.5: Settings → "Try to fix character-swap mods" (off by default) also tells Slotsloader: an empty
    // swap_repairs.txt beside variant_choices.json turns its swap repairs on. Synced at start-up, every refresh
    // and when the setting changes; Slotsloader rebuilds when the file appears or goes.
    internal static class SwapRepairFlag
    {
        internal const string FileName = "swap_repairs.txt";
        internal static string FilePath(string gameRoot) { return System.IO.Path.Combine(gameRoot, @"reframework\data\SF6_Costumes_Data", FileName); }

        internal static void Sync(string gameRoot, bool enabled)
        {
            if (String.IsNullOrEmpty(gameRoot) || !System.IO.Directory.Exists(System.IO.Path.Combine(gameRoot, "reframework"))) return;
            string file = FilePath(gameRoot);
            try
            {
                if (LinuxPlatform.IsLinux && enabled != System.IO.File.Exists(file))
                { LinuxPlatform.RequireClosed("change swap-repair settings"); LinuxPlatform.CanonicalRoot(gameRoot, "game"); Safety.NoReparseChain(file); }
                if (enabled && !System.IO.File.Exists(file)) { System.IO.Directory.CreateDirectory(System.IO.Path.GetDirectoryName(file)); using (System.IO.File.Create(file)) { } }
                else if (!enabled && System.IO.File.Exists(file)) System.IO.File.Delete(file);
            }
            catch (Exception ex) { if (ex is System.IO.IOException || ex is UnauthorizedAccessException) { Program.LogLine("Swap repair setting not passed to Slotsloader (" + ex.GetType().Name + ")."); return; } throw; }
        }
    }
}
